/bin/bash -lc "set -o pipefail
curl -fsSL --compressed https://submit.palomar-registry.org/ \\
  | awk '
      /<(input|textarea)/ { block="'$0; collecting=1; next }
      collecting { block=block " " $0 }
      collecting && />/ {
        if (block ~ /name=/) print block;
        block=""; collecting=0
      }
    '"' \\
  | sed -E 's/[[:space:]]+/ /g; s/"'^ //'"'"

